# ==================== HEARTBEAT ====================
def start_bot(config, device_id):
    uid = config["uid"]
    join_frame_bytes = bytes.fromhex(config["join_frame_hex"].replace(" ", "").replace("\n", ""))

    def on_open(ws):
        print(f"✅ Bot {uid} connected with device {device_id}.")
        ws.send(join_frame_bytes, websocket.ABNF.OPCODE_BINARY)
        print(f"🚀 Bot {uid} sent Channel.Enter (active).")

        def heartbeat():
            while True:
                time.sleep(20)
                try:
                    ws.send(join_frame_bytes, websocket.ABNF.OPCODE_BINARY)
                except:
                    break
        threading.Thread(target=heartbeat, daemon=True).start()

    def on_ping(ws, data):
        ws.send(data, websocket.ABNF.OPCODE_PONG)

    def on_error(ws, err):
        print(f"⚠️ Bot {uid} Error: {err}")

    def on_close(ws, a, b):
        print(f"❌ Bot {uid} disconnected. Reconnecting in 5s...")
        time.sleep(5)
        start_bot(config, device_id)

    ws_url = f"wss://i-875.olaparty.com/ikxd_cproxy?token={uid}"
    headers = {
        "X-Auth-Token": config["auth_token"],
        "X-DeviceId": device_id,
        "X-DeviceType": "Google Pixel 4",
        "X-App-Name": "olaparty",
        "X-OsType": "android",
        "X-CpuArch": "aarch64",
        "X-App-Channel": "official",
        "X-Sdk-Ver": "30",
        "X-SimCIso": "in",
        "X-Client-Net": "1",
        "X-BuildCode": "3185",
        "X-App-LastVer": "",
        "X-Apk-Abi": "abi64",
        "X-Lang": "en_in",
        "X-App-Ver": "52303",
        "X-App-Real-Ver": "52303",
        "X-Os-Ver": "11",
        "X-Pcid": "1152921504624773252",
        "X-Request-WsId": str(int(time.time()*1000)),
        "X-Last-Seqid": "0",
        "Origin": "wss://i-875.olaparty.com",
        "User-Agent": "com.live.party/3185 (Linux; U; Android 11; en_IN; Pixel 4; Build/RD2A.211001.002; Cronet/93.0.4533.0)"
    }
    ws = websocket.WebSocketApp(ws_url, header=headers, on_open=on_open,
                                on_ping=on_ping, on_error=on_error, on_close=on_close)
    ws.run_forever(ping_interval=20, ping_timeout=10)

# ==================== START ALL BOTS ====================
def start_all_bots():
    print("=== OlaParty 25 Bots Starting (Unique Device IDs) ===")
    for i, bot in enumerate(BOTS):
        device_id = DEVICE_IDS[i]
        thread = threading.Thread(target=start_bot, args=(bot, device_id))
        thread.daemon = True
        thread.start()
        time.sleep(2)

print("⚡ Bot script loaded! Starting Flask + Bots...")
threading.Thread(target=keep_alive, daemon=True).start()
threading.Thread(target=start_all_bots, daemon=True).start()

